def write_project_driver(directory: Path, records: list[dict[str, object]]) -> Path:
    driver = r"""function task025_project_study(output_file)
records = {
__RECORDS__
};
fid = fopen(output_file, 'w');
if fid < 0
    error('Could not open project-study output.');
end
for case_idx = 1:size(records, 1)
    result = RunOspreyJob(records{case_idx, 2});
    if ~isfield(result, 'quantify')
        error('The high-level project workflow returned no inspectable quantitative result.');
    end
    completed = isfield(result, 'flags') && isfield(result.flags, 'didQuantify') && result.flags.didQuantify;
    [value_count, finite_count, sum_squares] = task025_numeric_summary(result.quantify);
    l2_norm = sqrt(sum_squares);
    fprintf(fid, 'quantitative_report\t%s\t%d\t%d\t%d\t%.17g\n', ...
        records{case_idx, 1}, completed, value_count, finite_count, l2_norm);
end
fclose(fid);
end
""" + numeric_summary_function()
    driver = driver.replace("__RECORDS__", ";...\n".join(checkpoint_rows(records)))
    path = directory / "task025_project_study.m"
    path.write_text(driver, encoding="utf-8")
    return path


def run_octave(
    octave: str,
    generated_dir: Path,
    source_paths: list[Path],
    expression: str,
) -> str:
    setup = "".join(
        "addpath('%s', '-end');" % octave_quote(str(path)) for path in source_paths
    )
    setup += "addpath('%s', '-begin');" % octave_quote(str(generated_dir))
    completed = subprocess.run(
        [octave, "--no-gui", "--quiet", "--eval", setup + expression],
        cwd=generated_dir,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
        timeout=240,
    )
    if completed.returncode != 0:
        raise RuntimeError(
            "Octave workflow failed with exit code %s:\n%s"
            % (completed.returncode, completed.stdout)
        )
    return completed.stdout


def parse_observations(paths: list[Path]) -> dict[str, dict[str, object]]:
    observed: dict[str, dict[str, object]] = {
        "edited_model": {},
        "quantitative_report": {},
    }
    for path in paths:
        if not path.is_file():
            raise RuntimeError(f"workflow did not produce {path.name}")
        for line in path.read_text(encoding="utf-8").splitlines():
            fields = line.split("\t")
            kind = fields[0]
            if kind == "edited_model" and len(fields) == 7:
                record_id = fields[1]
                result = {
                    "sequence": fields[2],
                    "completed": fields[3] == "1",
                    "numeric_value_count": int(fields[4]),
                    "finite_value_count": int(fields[5]),
                    "numeric_l2_norm": float(fields[6]),
                }
            elif kind == "quantitative_report" and len(fields) == 6:
                record_id = fields[1]
                result = {
                    "completed": fields[2] == "1",
                    "numeric_value_count": int(fields[3]),
                    "finite_value_count": int(fields[4]),
                    "numeric_l2_norm": float(fields[5]),
                }
            else:
                raise RuntimeError(f"malformed workflow output: {line!r}")
            panel = observed[kind]
            if record_id in panel:
                raise RuntimeError(f"duplicate workflow record: {kind}/{record_id}")
            panel[record_id] = result
    return observed


def panel_report(
    records: list[dict[str, object]], observed: dict[str, dict[str, object]]
) -> dict[str, object]:
    expected_ids = {str(record["record_id"]) for record in records}
    if set(observed) != expected_ids:
        missing = sorted(expected_ids - set(observed))
        extra = sorted(set(observed) - expected_ids)
        raise RuntimeError(
            f"workflow record mismatch: missing={missing}, extra={extra}"
        )

    rows: list[dict[str, object]] = []
    for record in records:
        record_id = str(record["record_id"])
        result = observed[record_id]
        value_count = int(result["numeric_value_count"])
        finite_count = int(result["finite_value_count"])
        l2_norm = float(result["numeric_l2_norm"])
        if not bool(result["completed"]):
            raise RuntimeError(f"workflow did not complete: {record_id}")
        if value_count <= 0 or finite_count != value_count:
            raise RuntimeError(
                f"workflow produced incomplete numeric observations: {record_id}"
            )
        if not math.isfinite(l2_norm):
            raise RuntimeError(
                f"workflow produced a non-finite numeric summary: {record_id}"
            )
        rows.append(
            {
                "record_id": record_id,
                **result,
                "workflow_completed": True,
            }
        )
    return {"records": rows, "workflow_completed": True}


def run_workflow(
    manifest: dict[str, object],
) -> tuple[dict[str, str], dict[str, object]]:
    octave = shutil.which("octave")
    if octave is None:
        raise RuntimeError("GNU Octave is not available")

    entrypoints = [
        SOURCE_ROOT / "fit" / "OspreyFit.m",
        SOURCE_ROOT / "utilities" / "RunOspreyJob.m",
    ]
    missing = [
        str(path.relative_to(TASK_DIR)) for path in entrypoints if not path.is_file()
    ]
    if missing:
        raise RuntimeError(
            "missing supplied project entrypoints: " + ", ".join(missing)
        )

    if GENERATED_DIR.exists():
        shutil.rmtree(GENERATED_DIR)
    model_dir = GENERATED_DIR / "model"
    project_dir = GENERATED_DIR / "project"
    panels = manifest["panels"]
    model_records = list(panels["edited_model"])
    project_records = list(panels["quantitative_report"])

    write_model_shims(model_dir)
    write_model_driver(model_dir, model_records)
    model_output = model_dir / "observed.tsv"
    model_stdout = run_octave(
        octave,
        model_dir,
        [
            SOURCE_ROOT / "fit",
            SOURCE_ROOT / "libraries" / "FID-A" / "fitTools" / "fitModels" / "Osprey",
            SOURCE_ROOT / "libraries" / "FID-A" / "processingTools",
        ],
        "task025_fit_study('%s');" % octave_quote(str(model_output)),
    )

    write_project_shims(project_dir)
    write_project_driver(project_dir, project_records)
    project_output = project_dir / "observed.tsv"
    project_stdout = run_octave(
        octave,
        project_dir,
        [SOURCE_ROOT / "utilities", SOURCE_ROOT / "quantify"],
        "task025_project_study('%s');" % octave_quote(str(project_output)),
    )

    observed = parse_observations([model_output, project_output])
    reports = {
        "edited_model": panel_report(model_records, observed["edited_model"]),
        "quantitative_report": panel_report(
            project_records, observed["quantitative_report"]
        ),
    }
    stdout = {
        "edited_model": model_stdout[-500:],
        "quantitative_report": project_stdout[-500:],
    }
    return stdout, reports


def emit_report(report: dict[str, object]) -> None:
    serialized = json.dumps(
        report,
        indent=2,
        sort_keys=True,
        allow_nan=False,
    )
    OUTPUT_DIR.mkdir(exist_ok=True)
    REPORT_FILE.write_text(serialized + "\n", encoding="utf-8")
    print(serialized)


def main() -> int:
    manifest = json.loads(MANIFEST_FILE.read_text(encoding="utf-8"))
    report: dict[str, object] = {
        "offline": True,
        "workflow": "run high-level Osprey checkpoint studies",
        "report_file": str(REPORT_FILE.relative_to(TASK_DIR)),
        "status_contract": {
            "workflow_completed": "Both high-level project workflows returned complete finite inspectable observations.",
            "runner_failure": "A high-level workflow failed or returned missing or non-finite observations.",
        },
    }
    try:
        octave_stdout, panels = run_workflow(manifest)
        report["panels"] = panels
        report["octave_stdout_tail"] = octave_stdout
        report["status"] = "workflow_completed"
        report["reproduction_completed"] = True
        emit_report(report)
        return 0
    except Exception as exc:
        report["status"] = "runner_failure"
        report["reproduction_completed"] = False
        report["error"] = f"{type(exc).__name__}: {exc}"
        emit_report(report)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

{
  "description": "Offline checkpoints from one synthetic phantom validation study.",
  "panels": {
    "edited_model": [
