            dataToFit.refFWHM   = fitParamsOff.refFWHM;

            if ~strcmp(fitOpts.coMM3, 'none')
                [basisSetDiff1] = osp_addDiffMMPeaks(basisSetDiff1,basisSetOff,fitOpts);
