function [BASISdiff] = osp_addDiffMMPeaks(BASISdiff,BASISoff,fitOpts)
%   Adds the co-edited macromolecular signal at 3 ppm to the difference
%   basis set.
%
%   BASISoff has to be a reference basis set on the same amplitude
%   convention as the difference basis functions, i.e. a single acquisition
%   state (edit-OFF/'A' sub-spectrum). Difference basis functions are
%   combinations of the individual acquisition states with coefficients
%   +/-1, so a summed sub-spectrum (SUM = A+B[+C+D]) is scaled by the
%   number of combined states and must not be used as reference here - it
%   would scale the co-edited MM3 signal by that same factor and break the
%   fixed area relationships ('1to1GABA', '3to2MM', ...) as well as the
%   comparability of MEGA, HERMES, and HERCULES results.
    n = BASISdiff.n;
    sw = BASISdiff.spectralwidth;
    Bo = BASISdiff.Bo;
    centerFreq = BASISdiff.centerFreq;
    % The amplitude and FWHM values are determined as for the LCModel and
    % TARQUIN algorithms (see Wilson et al., MRM 2011).
    hzppm = Bo*42.577;

    % To scale the amplitudes correctly, we first need to determine the
    % area of the 3.027 ppm CH3 signal of creatine. If a reference basis set
    % with several sub-spectra is handed over, use its first (edit-OFF)
    % sub-spectrum, which is also the one that fit_makeBasis uses to scale
    % the MM and lipid basis functions.
    if ndims(BASISoff.specs) > 2 && size(BASISoff.specs,3) > 1
        BASISoff.fids  = BASISoff.fids(:,:,1);
        BASISoff.specs = BASISoff.specs(:,:,1);
    end
    [CrArea] = detCrArea(BASISoff);
    oneProtonArea = CrArea/3;

