function task025_probe2(checkpoint_file, seq_override, coMM3, fwhm, bo_scale, cr_scale)
checkpoint = load(checkpoint_file);
if nargin > 4 && ~isempty(bo_scale)
    checkpoint.field_strength = checkpoint.field_strength * bo_scale;
end
names0 = task025_strings(checkpoint.component_names);
if nargin > 5 && ~isempty(cr_scale)
    idx_Cr = find(strcmp(names0,'Cr'));
    checkpoint.specs(:, idx_Cr, :) = checkpoint.specs(:, idx_Cr, :) * cr_scale;
    checkpoint.fids(:, idx_Cr, :)  = checkpoint.fids(:, idx_Cr, :) * cr_scale;
end
if ~isempty(coMM3)
    checkpoint.model_option = coMM3;
end
if ~isempty(seq_override)
    checkpoint.sequence = seq_override;
end
container = task025_fit_container(checkpoint, fullfile(pwd, 'ignored.mat'));
if nargin > 3 && ~isempty(fwhm)
    container.opts.fit.FWHMcoMM3 = fwhm;
end
result = OspreyFit(container);
seq = task025_text(checkpoint.sequence);
diffIdx = double(checkpoint.difference_index(1));
res = result.fit.resBasisSet.metab.spec_1{1,1,2};
orig = checkpoint.specs(:, :, diffIdx);
total = 0;
for c = 1:size(res.specs,2)
    if c <= size(orig,2)
        total = total + sum(real(res.specs(:,c) - orig(:,c)));
    else
        total = total + sum(real(res.specs(:,c)));
    end
end
addedl2 = 0; addedmax = 0;
for c = 1:size(res.specs,2)
    if c <= size(orig,2)
        d = res.specs(:,c) - orig(:,c);
    else
        d = res.specs(:,c);
    end
    addedl2 = addedl2 + sum(abs(d).^2);
    addedmax = max(addedmax, max(real(d)));
end
fprintf('   l2(added) = %.9f  peak(added) = %.9f\n', sqrt(addedl2), addedmax);
fprintf('%-9s %-12s Bo=%.2f FWHM=%5.1f CrScale=%4.2f -> coMM3 area = %.9f (ncols %d, names %s)\n', ...
    seq, task025_text(checkpoint.model_option), double(checkpoint.field_strength(1)), ...
    container.opts.fit.FWHMcoMM3, size(res.specs,2)*0+ (nargin>5 && ~isempty(cr_scale))*cr_scale + (nargin<=5 || isempty(cr_scale))*1, ...
    total, size(res.specs,2), strjoin(res.name, ','));
end

