function value = task025_text(raw)
if iscell(raw)
    raw = raw{1};
end
value = strtrim(char(raw));
end

function [value_count, finite_count, sum_squares] = task025_numeric_summary(value)
value_count = 0;
finite_count = 0;
sum_squares = 0;
if isnumeric(value) || islogical(value)
    flat = value(:);
    finite_mask = isfinite(real(flat)) & isfinite(imag(flat));
    value_count = numel(flat);
    finite_count = sum(finite_mask);
    if finite_count == value_count
        sum_squares = sum(abs(flat) .^ 2);
    else
        sum_squares = NaN;
    end
elseif iscell(value)
    for item_idx = 1:numel(value)
        [child_count, child_finite, child_sum] = task025_numeric_summary(value{item_idx});
        value_count = value_count + child_count;
        finite_count = finite_count + child_finite;
        sum_squares = sum_squares + child_sum;
    end
elseif isstruct(value)
    for item_idx = 1:numel(value)
        names = fieldnames(value(item_idx));
        for field_idx = 1:numel(names)
            child = value(item_idx).(names{field_idx});
            [child_count, child_finite, child_sum] = task025_numeric_summary(child);
            value_count = value_count + child_count;
            finite_count = finite_count + child_finite;
            sum_squares = sum_squares + child_sum;
        end
    end
end
end
